-- REST||ART INTEGRACE - import dokumentů pro programové dotazníky v2.0 RC1
-- Před importem spusťte release insert nebo nastavte @release_id ručně.
SET @release_id := (SELECT id FROM rest_art_document_releases WHERE release_code = 'REST_ART_PROGRAMOVE_DOTAZNIKY_V2_0_RC1' ORDER BY id DESC LIMIT 1);

